<?php
/* THE WALL installer - wall. Writes three new files and adds one script line to the desk.
   All-or-nothing: if any patch anchor is missing, nothing is written. Backs up what it changes. */
if (($_GET['go'] ?? '') !== '4190531d39394596') { http_response_code(404); exit; }
header('Content-Type: text/plain; charset=utf-8');
$root = preg_match('~/_inst~', __DIR__) ? dirname(__DIR__) : __DIR__;
$tag  = 'wall';
$stamp = date('Ymd');
$blocks  = json_decode(base64_decode(''), true);
$patches = json_decode(base64_decode('W1siZGVzay9pbmRleC5odG1sIiwgIjxzY3JpcHQgc3JjPVwibGFiLmpzP3Y9MVwiPjwvc2NyaXB0PiIsICI8c2NyaXB0IHNyYz1cImxhYi5qcz92PTFcIj48L3NjcmlwdD5cbjxzY3JpcHQgc3JjPVwid2FsbC5qcz92PTFcIj48L3NjcmlwdD4iLCAibG9hZCBUaGUgV2FsbCBtb2R1bGUiXV0='), true);
$log = []; $wrote = []; $bak = [];
function out($s) { global $log; $log[] = $s; echo $s . "\n"; }

/* 1. check every patch anchor BEFORE touching anything */
$ready = [];
foreach ($patches as $p) {
  [$rel, $anchor, $repl, $note] = $p;
  $f = $root . '/' . $rel;
  if (!is_file($f)) { out("MISSING FILE: $rel"); exit; }
  $cur = file_get_contents($f);
  if (strpos($cur, $repl) !== false) { out("already applied: $rel ($note)"); continue; }
  $n = substr_count($cur, $anchor);
  if ($n !== 1) { out("ANCHOR x$n in $rel ($note) - nothing written"); exit; }
  $ready[] = [$f, $rel, $cur, str_replace($anchor, $repl, $cur), $note];
}

/* 2. new files */
foreach ($blocks as $rel => $b64) {
  $f = $root . '/' . $rel;
  $dir = dirname($f);
  if (!is_dir($dir) && !@mkdir($dir, 0755, true)) { out("CANNOT MAKE DIR: " . dirname($rel)); exit; }
  if (is_file($f)) { $bk = $f . '.bak-' . $stamp . '-' . $tag; @copy($f, $bk); $bak[] = $bk; }
  $body = base64_decode($b64);
  if (@file_put_contents($f, $body) === false) { out("CANNOT WRITE: $rel"); exit; }
  if (substr($rel, -4) === '.php') {
    $chk = [];
    exec('php -l ' . escapeshellarg($f) . ' 2>&1', $chk, $rc);
    if ($rc !== 0) { out("PHP LINT FAILED on $rel: " . implode(' ', $chk)); @unlink($f); exit; }
  }
  $wrote[] = $rel;
  out("wrote $rel (" . strlen($body) . " bytes)");
}

/* 3. apply the patches */
foreach ($ready as [$f, $rel, $cur, $new, $note]) {
  $bk = $f . '.bak-' . $stamp . '-' . $tag;
  if (!is_file($bk)) @copy($f, $bk);
  if (@file_put_contents($f, $new) === false) { out("PATCH WRITE FAILED: $rel"); exit; }
  out("patched $rel ($note)");
}

/* 4. seed the channels and settings so the first visit is not empty */
$api = $root . '/api/wall.php';
if (is_file($api)) {
  $data = null;
  foreach ([dirname($root) . '/tt_data', dirname($root, 2) . '/tt_data'] as $c) if (is_dir($c)) { $data = $c; break; }
  if ($data) {
    $wf = $data . '/wall.json';
    $d = is_file($wf) ? json_decode((string)file_get_contents($wf), true) : [];
    if (!is_array($d)) $d = [];
    if (empty($d['channels'])) {
      $d['channels'] = [
        'wall' => ['key'=>'wall','name'=>'The Wall','blurb'=>'Everything. Start here.','order'=>1,'post'=>'all','icon'=>"\u{1F9F1}"],
        'fits' => ['key'=>'fits','name'=>'Fit Check','blurb'=>'Show what you are wearing. Tag the product.','order'=>2,'post'=>'all','icon'=>"\u{1F4F8}"],
        'wins' => ['key'=>'wins','name'=>'Wins','blurb'=>'Sales, orders, answered prayers. Post the win.','order'=>3,'post'=>'all','icon'=>"\u{1F3C6}"],
        'amb'  => ['key'=>'amb','name'=>'Ambassadors','blurb'=>'Links, drops and what is selling.','order'=>4,'post'=>'all','icon'=>"\u{1F91D}"],
        'word' => ['key'=>'word','name'=>'A Word','blurb'=>'Scripture, encouragement, a line that carried you.','order'=>5,'post'=>'all','icon'=>"\u{1F54A}"],
        'news' => ['key'=>'news','name'=>'Announcements','blurb'=>'From the top. Drops, deadlines, changes.','order'=>6,'post'=>'admin','icon'=>"\u{1F4E3}"],
      ];
      @file_put_contents($wf, json_encode($d, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));
      out('seeded the channels');
    } else { out('channels already there'); }
    $imgdir = $data . '/wall/img';
    if (!is_dir($imgdir)) { @mkdir($imgdir, 0750, true); out('made the photo folder'); }
    out('data folder: ' . $data);
  } else { out('NOTE: could not find tt_data - The Wall will make it on first use'); }
}
out('--- DONE. backups: ' . (count($bak) ?: 0) . ' ---');
@unlink(__FILE__);
